/* Radiant Central Coast: home-coming-up events embed. Generated by clients/build_client_embeds.py; don't edit.
   Paste into a Squarespace Code Block:
   <div data-cc-embed="home-coming-up"></div><script src="https://legacyco.github.io/radiant-events/embeds/home-coming-up.js"></script>
*/
(function () {
  var name = "home-coming-up";
  var host = document.querySelector('[data-cc-embed="' + name + '"]:not([data-cc-ready])');
  if (!host) {
    // No container in the snippet: put one right where the script tag is.
    var me = document.currentScript;
    if (!me || !me.parentNode) return;
    host = document.createElement("div");
    me.parentNode.insertBefore(host, me);
  }
  if (!document.querySelector('style[data-cc-style="' + name + '"]')) {
    var style = document.createElement("style");
    style.setAttribute("data-cc-style", name);
    style.textContent = "  .cc-events {\n    /* BRAND: change these to match the site */\n    --cc-accent: #474D47;          /* button + active tab color */\n    --cc-accent-text: #FCF2BF;\n    --cc-muted: rgba(71, 77, 71, .8);\n    --cc-border: rgba(190, 173, 147, .7);\n    --cc-card-bg: transparent;\n    --cc-radius: 0px;          /* card corners */\n    --cc-btn-radius: 300px;       /* button corners */\n    font-family: inherit;\n    color: inherit;\n    max-width: 1100px;\n    margin: 0 auto;\n  }\n  .cc-events__tabs { display: flex; gap: 8px; margin-bottom: 24px; flex-wrap: wrap; }\n  .cc-events__tab {\n    font: inherit; font-size: .9rem; letter-spacing: .04em; text-transform: uppercase;\n    padding: 10px 18px; border: 1px solid var(--cc-border); border-radius: 999px;\n    background: transparent; color: inherit; cursor: pointer;\n  }\n  .cc-events__tab.is-active { background: var(--cc-accent); color: var(--cc-accent-text); border-color: var(--cc-accent); }\n  .cc-events__list { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 24px; }\n  .cc-event {\n    display: flex; flex-direction: column; border: 1px solid var(--cc-border);\n    border-radius: var(--cc-radius); overflow: hidden; background: var(--cc-card-bg);\n  }\n  .cc-event__img { aspect-ratio: 16 / 9; width: 100%; object-fit: cover; display: block; background: var(--cc-border); }\n  .cc-event__body { padding: 18px 20px 20px; display: flex; flex-direction: column; gap: 8px; flex: 1; }\n  .cc-event__date { font-size: .85rem; letter-spacing: .05em; text-transform: uppercase; color: var(--cc-muted); margin: 0; }\n  .cc-event__title { font-size: 1.25rem; line-height: 1.25; margin: 0; }\n  .cc-event__meta, .cc-event__summary { margin: 0; font-size: .95rem; color: var(--cc-muted); overflow-wrap: anywhere; }\n  .cc-event__badge {\n    align-self: flex-start; font-size: .7rem; letter-spacing: .08em; text-transform: uppercase;\n    padding: 3px 8px; border-radius: 4px; background: var(--cc-accent); color: var(--cc-accent-text);\n  }\n  .cc-event__actions { margin-top: auto; padding-top: 10px; display: flex; gap: 10px; flex-wrap: wrap; }\n  .cc-event__btn {\n    display: inline-block; padding: 10px 16px; border-radius: var(--cc-btn-radius); font-size: .9rem;\n    text-decoration: none !important; border: 1px solid var(--cc-accent);\n  }\n  .cc-event__btn--primary { background: var(--cc-accent); color: var(--cc-accent-text) !important; }\n  .cc-event__btn--ghost { background: transparent; color: inherit !important; }\n  .cc-events__msg { grid-column: 1 / -1; color: var(--cc-muted); }\n  .cc-events__more {\n    display: block; margin: 28px auto 0; font: inherit; padding: 10px 22px; cursor: pointer;\n    border: 1px solid var(--cc-border); border-radius: 999px; background: transparent; color: inherit;\n  }\n  .cc-events__more[hidden], .cc-events__stale[hidden], .cc-events__tabs[hidden] { display: none; }\n  .cc-events__all {\n    display: table; margin: 28px auto 0; padding: 10px 22px; border: 1px solid var(--cc-accent);\n    border-radius: var(--cc-btn-radius); color: inherit !important; text-decoration: none !important;\n  }\n  .cc-events__stale {\n    margin: 0 0 20px; padding: 12px 16px; border: 1px solid var(--cc-border);\n    border-radius: var(--cc-radius); font-size: .9rem; color: var(--cc-muted);\n  }\n  .cc-events__stale a { color: inherit; }\n  .cc-events--past .cc-event { opacity: .85; }\n  .cc-cal { margin-top: 12px; font-size: .85rem; }\n  .cc-cal summary {\n    display: inline-block; cursor: pointer; list-style: none; color: var(--cc-muted);\n    text-decoration: underline; text-underline-offset: 3px;\n  }\n  .cc-cal summary::-webkit-details-marker { display: none; }\n  .cc-cal__links { display: flex; flex-wrap: wrap; gap: 6px 16px; margin-top: 8px; }\n  .cc-cal__links a { color: inherit !important; }\n  .cc-events__subscribe { margin: 28px auto 0; text-align: center; }\n  .cc-events__subscribe .cc-cal__links { justify-content: center; }";
    document.head.appendChild(style);
  }
  host.className = "cc-events";
  host.setAttribute("aria-live", "polite");
  host.innerHTML = "  <div class=\"cc-events__tabs\" role=\"tablist\">\n    <button class=\"cc-events__tab is-active\" role=\"tab\" aria-selected=\"true\" data-view=\"upcoming\"></button>\n    <button class=\"cc-events__tab\" role=\"tab\" aria-selected=\"false\" data-view=\"past\"></button>\n  </div>\n  <p class=\"cc-events__stale\" hidden></p>\n  <div class=\"cc-events__list\"><p class=\"cc-events__msg\"></p></div>\n  <button class=\"cc-events__more\" hidden></button>";
  window.ccEventsTarget = host;
})();
(function () {
  var CONFIG = {
    FEED_URL: "https://legacyco.github.io/radiant-events/events.json",
    TIMEZONE: "America/Los_Angeles",
    USE_CHURCH_CENTER_MODAL: true,
    COLLAPSE_RECURRING: true,
    FEATURED_ONLY: false,        // true = only events starred as Featured in Planning Center
    PAGE_SIZE: 12,
    LAYOUT: "compact",              // "compact" = next few upcoming events, no tabs
    COMPACT_COUNT: 3,
    EVENTS_PAGE_URL: "/events",         // compact layout: adds a "See all events" link here, e.g. "/events"
    INCLUDE: [],                 // e.g. ["Español"]: only events with one of these in the title
    EXCLUDE: [],                 // e.g. ["Staff"]: hide events with one of these in the title
    LOCALE: "en-US",             // date language, e.g. "es-US"
    TEXT: {"upcoming": "Upcoming", "past": "Past events", "loading": "Loading events…", "more": "Show more", "register": "Register", "details": "Details", "featured": "Featured", "seeAll": "See all events", "noUpcoming": "No upcoming events right now. Check back soon.", "noPast": "No past events yet.", "error": "Events couldn't load right now. Please refresh in a minute.", "stale": "This list may be out of date. ", "staleLink": "See the latest events on Church Center.", "addToCalendar": "Add to calendar", "google": "Google Calendar", "appleOutlook": "Apple / Outlook", "subscribe": "Subscribe to this calendar"},
    ADD_SEO_SCHEMA: false,        // adds schema.org Event data for upcoming events
    SHOW_DETAILS_WITH_REGISTER: false,  // false = events with a registration show only Register
    ADD_TO_CALENDAR: true,       // "Add to calendar" on upcoming events (Google, Apple / Outlook)
    SUBSCRIBE_LINK: true,        // full layout: "Subscribe to this calendar" under the list
    STALE_AFTER_HOURS: 36,       // the sync runs hourly; older than this means it stopped
    CHURCH_CENTER_URL: "https://radiantcentralcoast.churchcenter.com/calendar"        // e.g. "https://yourchurch.churchcenter.com/calendar", linked in the stale note
  };

  // Each Code Block's script runs right after its own markup, so the first
  // container nobody has claimed yet is this one.
  // The hosted version (clients/<church>/embeds/*.js) hands over its own container;
  // the pasted version takes the first one nobody has claimed.
  var root = window.ccEventsTarget || document.querySelector(".cc-events:not([data-cc-ready])");
  window.ccEventsTarget = null;
  if (!root) return;
  root.setAttribute("data-cc-ready", "1");
  var T = CONFIG.TEXT;
  var list = root.querySelector(".cc-events__list");
  var moreBtn = root.querySelector(".cc-events__more");
  var tabs = root.querySelectorAll(".cc-events__tab");
  tabs[0].textContent = T.upcoming;
  tabs[1].textContent = T.past;
  list.firstChild.textContent = T.loading;
  moreBtn.textContent = T.more;
  var state = { all: [], view: "upcoming", shown: 0 };
  var compact = CONFIG.LAYOUT === "compact";
  if (compact) {
    root.querySelector(".cc-events__tabs").hidden = true;
    if (CONFIG.EVENTS_PAGE_URL) {
      var all = el("a", "cc-events__all", T.seeAll);
      all.href = CONFIG.EVENTS_PAGE_URL;
      root.appendChild(all);
    }
  }
  if (!compact && CONFIG.SUBSCRIBE_LINK && feedFile("events.ics")) {
    // webcal:// makes Apple Calendar and Outlook subscribe instead of importing once.
    var webcal = feedFile("events.ics").replace(/^https?:/, "webcal:");
    root.appendChild(calMenu(T.subscribe, [
      [T.google, "https://calendar.google.com/calendar/r?cid=" + encodeURIComponent(webcal), true],
      [T.appleOutlook, webcal, false]
    ], "cc-cal cc-events__subscribe"));
  }

  // ── Formatting ───────────────────────────────────────────────
  function fmt(iso, opts) {
    return new Intl.DateTimeFormat(CONFIG.LOCALE, Object.assign({ timeZone: CONFIG.TIMEZONE }, opts)).format(new Date(iso));
  }
  function dateLine(e) {
    var day = fmt(e.start, { weekday: "short", month: "short", day: "numeric", year: "numeric" });
    var endDay = fmt(e.end, { weekday: "short", month: "short", day: "numeric", year: "numeric" });
    if (e.all_day) {
      // all-day ends are inclusive in Planning Center, so compare calendar days
      return day === endDay ? day : day + " – " + endDay;
    }
    var t1 = fmt(e.start, { hour: "numeric", minute: "2-digit" });
    var t2 = fmt(e.end, { hour: "numeric", minute: "2-digit" });
    return day === endDay ? day + " · " + t1 + " – " + t2 : day + " " + t1 + " – " + endDay + " " + t2;
  }

  // ── Data shaping ─────────────────────────────────────────────
  // Case- and accent-blind, so "espanol" matches "Español".
  function fold(text) {
    return String(text || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  }
  function titleHas(e, words) {
    var title = fold(e.title);
    return words.some(function (w) { return title.indexOf(fold(w)) !== -1; });
  }
  function eventsFor(view) {
    var now = Date.now();
    var items = state.all.filter(function (e) {
      if (CONFIG.FEATURED_ONLY && !e.featured) return false;
      if (CONFIG.INCLUDE.length && !titleHas(e, CONFIG.INCLUDE)) return false;
      if (CONFIG.EXCLUDE.length && titleHas(e, CONFIG.EXCLUDE)) return false;
      // decide by end time in the browser, so a feed that's a few hours old is still right
      var isPast = new Date(e.end).getTime() < now;
      return view === "past" ? isPast : !isPast;
    });
    if (view === "past") items.reverse(); // newest first
    if (CONFIG.COLLAPSE_RECURRING) {
      var seen = {};
      items = items.filter(function (e) {
        if (!e.recurrence) return true;
        if (seen[e.event_id]) return false;
        return (seen[e.event_id] = true);
      });
    }
    return items;
  }

  // ── Rendering (textContent only, so feed text can't inject HTML) ──
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }
  function link(href, label, cls, modal) {
    var a = el("a", "cc-event__btn " + cls, label);
    a.href = href;
    if (modal) a.setAttribute("data-open-in-church-center-modal", "true");
    else { a.target = "_blank"; a.rel = "noopener"; }
    return a;
  }
  function card(e, view) {
    var c = el("article", "cc-event");
    if (e.image) {
      var img = el("img", "cc-event__img");
      img.src = e.image; img.alt = ""; img.loading = "lazy";
      img.onerror = function () { img.remove(); };
      c.appendChild(img);
    }
    var b = el("div", "cc-event__body");
    if (e.featured && view === "upcoming") b.appendChild(el("span", "cc-event__badge", T.featured));
    b.appendChild(el("p", "cc-event__date", dateLine(e)));
    b.appendChild(el("h3", "cc-event__title", e.title));
    var meta = [e.location, CONFIG.COLLAPSE_RECURRING ? e.recurrence : ""].filter(Boolean).join(" · ");
    if (meta) b.appendChild(el("p", "cc-event__meta", meta));
    var blurb = e.summary || (e.description || "").split("\n")[0];
    if (blurb) b.appendChild(el("p", "cc-event__summary", blurb.length > 220 ? blurb.slice(0, 217) + "…" : blurb));

    var actions = el("div", "cc-event__actions");
    var modal = CONFIG.USE_CHURCH_CENTER_MODAL;
    if (view === "upcoming" && e.registration_url) {
      actions.appendChild(link(e.registration_url, T.register, "cc-event__btn--primary", modal));
    }
    var registerOnly = view === "upcoming" && e.registration_url && !CONFIG.SHOW_DETAILS_WITH_REGISTER;
    if (e.details_url && !registerOnly) {
      var primary = !actions.childNodes.length && view === "upcoming";
      actions.appendChild(link(e.details_url, T.details,
        primary ? "cc-event__btn--primary" : "cc-event__btn--ghost", modal));
    }
    if (actions.childNodes.length) b.appendChild(actions);
    if (view === "upcoming" && CONFIG.ADD_TO_CALENDAR) {
      b.appendChild(calMenu(T.addToCalendar, [
        [T.google, googleLink(e), true],
        [T.appleOutlook, e.ics ? feedFile(e.ics) : "", false]
      ], "cc-cal"));
    }
    c.appendChild(b);
    return c;
  }

  // ── Calendar links ──────────────────────────────────────────
  // Files the sync publishes next to events.json (events.ics, ics/<id>.ics).
  function feedFile(path) {
    try { return new URL(path, CONFIG.FEED_URL).href; } catch (err) { return ""; }
  }
  function ymd(iso) { return iso.slice(0, 10).replace(/-/g, ""); }
  function googleLink(e) {
    var dates;
    if (e.all_day) {
      var after = new Date(e.end_local.slice(0, 10) + "T00:00:00Z");
      after.setUTCDate(after.getUTCDate() + 1); // Google wants the day after the last day
      dates = ymd(e.start_local) + "/" + ymd(after.toISOString());
    } else {
      dates = e.start.replace(/[-:]/g, "") + "/" + e.end.replace(/[-:]/g, "");
    }
    var more = e.registration_url ? T.register + ": " + e.registration_url : e.details_url;
    var details = [e.summary || e.description, more].filter(Boolean).join("\n\n");
    return "https://calendar.google.com/calendar/render?" + new URLSearchParams({
      action: "TEMPLATE", text: e.title, dates: dates, details: details.slice(0, 1500), location: e.location || ""
    }).toString();
  }
  // A small disclosure menu: no extra script, works with keyboard and screen readers.
  function calMenu(label, links, cls) {
    var menu = el("details", cls);
    menu.appendChild(el("summary", "", label));
    var box = el("div", "cc-cal__links");
    links.forEach(function (l) {
      if (!l[1]) return;
      var a = el("a", "", l[0]);
      a.href = l[1];
      if (l[2]) { a.target = "_blank"; a.rel = "noopener"; }
      box.appendChild(a);
    });
    menu.appendChild(box);
    return menu;
  }

  function render(reset) {
    var items = eventsFor(state.view);
    if (reset) { list.textContent = ""; state.shown = 0; }
    root.classList.toggle("cc-events--past", state.view === "past");
    if (!items.length) {
      list.appendChild(el("p", "cc-events__msg",
        state.view === "past" ? T.noPast : T.noUpcoming));
    }
    var size = compact ? CONFIG.COMPACT_COUNT : CONFIG.PAGE_SIZE;
    var next = items.slice(state.shown, state.shown + size);
    next.forEach(function (e) { list.appendChild(card(e, state.view)); });
    state.shown += next.length;
    moreBtn.hidden = compact || state.shown >= items.length;
  }

  // ── SEO: schema.org Event markup ────────────────────────────
  function addSchema() {
    var upcoming = eventsFor("upcoming").slice(0, 25).map(function (e) {
      var ev = {
        "@context": "https://schema.org", "@type": "Event",
        name: e.title, startDate: e.start, endDate: e.end,
        eventStatus: "https://schema.org/EventScheduled",
        eventAttendanceMode: "https://schema.org/OfflineEventAttendanceMode",
        description: e.summary || e.description || undefined,
        image: e.image || undefined,
        url: e.registration_url || e.details_url || undefined
      };
      if (e.location) ev.location = { "@type": "Place", name: e.location, address: e.location };
      if (e.registration_url) ev.offers = { "@type": "Offer", url: e.registration_url, availability: "https://schema.org/InStock" };
      return ev;
    });
    if (!upcoming.length) return;
    var s = document.createElement("script");
    s.type = "application/ld+json";
    s.textContent = JSON.stringify(upcoming);
    document.head.appendChild(s);
  }

  // ── Stale feed check ────────────────────────────────────────
  // If the hourly sync stops, say so instead of quietly showing an old list.
  function checkStale(generatedAt) {
    var age = (Date.now() - new Date(generatedAt).getTime()) / 36e5;
    if (!generatedAt || isNaN(age) || age < CONFIG.STALE_AFTER_HOURS) return;
    console.warn("Church events feed is " + Math.round(age) + " hours old. Check the sync workflow.");
    var note = root.querySelector(".cc-events__stale");
    note.textContent = T.stale;
    if (CONFIG.CHURCH_CENTER_URL) {
      var a = el("a", "", T.staleLink);
      a.href = CONFIG.CHURCH_CENTER_URL; a.target = "_blank"; a.rel = "noopener";
      note.appendChild(a);
    }
    note.hidden = false;
  }

  // ── Church Center modal ─────────────────────────────────────
  function loadModal() {
    if (!CONFIG.USE_CHURCH_CENTER_MODAL || document.querySelector('script[src*="js.churchcenter.com/modal"]')) return;
    var s = document.createElement("script");
    s.src = "https://js.churchcenter.com/modal/v1";
    document.body.appendChild(s);
  }

  // ── Wire up ─────────────────────────────────────────────────
  Array.prototype.forEach.call(tabs, function (t) {
    t.addEventListener("click", function () {
      Array.prototype.forEach.call(tabs, function (o) {
        o.classList.toggle("is-active", o === t);
        o.setAttribute("aria-selected", o === t ? "true" : "false");
      });
      state.view = t.getAttribute("data-view");
      render(true);
    });
  });
  moreBtn.addEventListener("click", function () { render(false); });

  fetch(CONFIG.FEED_URL, { cache: "no-cache" })
    .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then(function (data) {
      state.all = data.events || [];
      checkStale(data.generated_at);
      render(true);
      if (CONFIG.ADD_SEO_SCHEMA) addSchema();
      loadModal();
    })
    .catch(function () {
      list.textContent = "";
      list.appendChild(el("p", "cc-events__msg", T.error));
    });
})();
